if __name__ == '__main__':
    assert len(p1_data) == 100, f"Expected 100 records, got {len(p1_data)}"
    for r in p1_data:
        assert r['vi'], f"Missing vi: {r}"
        assert len(r['vi']) <= 35, f"vi too long ({len(r['vi'])}): {r['vi']}"
        assert r['ipa'].startswith('/') and r['ipa'].endswith('/') and r['ipa'].count('/') == 2, f"Invalid ipa: {r['ipa']}"
        assert r['pos'] in ['noun', 'verb', 'adj', 'adv', 'num', 'intj', 'prep', 'pron', 'conj', 'det'], f"Invalid pos: {r['pos']}"
        assert r['status'] == 'reviewed', f"Invalid status: {r['status']}"
    print("All 100 records in Part 1 verified successfully!")
